@wp.func
def grid_vel_at(world: int, s: int, grid_mass: wp.array(dtype=float, ndim=2), momentum: wp.array(dtype=wp.vec3, ndim=2), impulse: wp.array(dtype=wp.vec3, ndim=2), old_v: wp.array(dtype=wp.vec3, ndim=2), new_v: wp.array(dtype=wp.vec3, ndim=2)):
    if grid_mass[world, s] > 0.0:
        old_v[world, s] = momentum[world, s] / grid_mass[world, s]
        new_v[world, s] = (momentum[world, s] + impulse[world, s]) / grid_mass[world, s]

