@wp.func
def couple_and_velocity_at(world: int, a: int, keys: wp.array(dtype=wp.int64, ndim=2), heads: wp.array(dtype=int, ndim=2), links: wp.array(dtype=int, ndim=2), grid_mass: wp.array(dtype=float, ndim=2), momentum: wp.array(dtype=wp.vec3, ndim=2), impulse: wp.array(dtype=wp.vec3, ndim=2), old_v: wp.array(dtype=wp.vec3, ndim=2), new_v: wp.array(dtype=wp.vec3, ndim=2), node_count: int):
    """Exactly Eq. 8 for two vectors, sharing the linked-list traversal."""
    if keys[world, a] < wp.int64(0) or grid_mass[world, a] <= 0.0:
        return
    node = int(keys[world, a] % wp.int64(node_count))
    code_a = keys[world, a] // wp.int64(node_count)
    total = float(0.0)
    dm = wp.vec3(0.0)
    di = wp.vec3(0.0)
    b = heads[world, node]
    while b >= 0:
        total += grid_mass[world, b]
        code_b = keys[world, b] // wp.int64(node_count)
        if b != a and compatible(code_a, code_b):
            dm += grid_mass[world, a] * momentum[world, b] - grid_mass[world, b] * momentum[world, a]
            di += grid_mass[world, a] * impulse[world, b] - grid_mass[world, b] * impulse[world, a]
        b = links[world, b]
    p = momentum[world, a] + dm / total
    j = impulse[world, a] + di / total
    old_v[world, a] = p / grid_mass[world, a]
    new_v[world, a] = (p + j) / grid_mass[world, a]

